        text: 'When someone says the word \'knitting\' we might well picture an elderly person - a grandmother perhaps - sitting by the fire knitting garments for themselves or other members of the family. It\'s a homely image, but one that may lead you to feel that knitting is an activity of the past - and, indeed, during the previous decade, it was one of the skills that was predicted to vanish from everyday life.',
